#!/usr/bin/env python3
"""Freeze an existing cap parameter contrast for predeclared closed batches."""
import ast,hashlib,json,pathlib
R=pathlib.Path(__file__).resolve().parents[1];base=R/'specs/L011-protocol-v2.json';p=json.loads(base.read_text());p['version']=1;p['scope']='CPU-only existing cap parameter contrast for fixed closed batches; no online oracle or serving change';p['single_factor']={'A':{'max_batch_size':32},'B':{'max_batch_size':'predeclared_case_cap'}};p['candidate_caps']={'tokenizer-cpu-c2':2,'tokenizer-cpu-c3':3};p['measurement_revision']={'base_protocol_sha256':hashlib.sha256(base.read_bytes()).hexdigest(),'reason':'L011 short wall penalty beyond AA with comparable CPU, long inconclusive. Test cap termination of collection at fixed2ms.','source_or_model_changes':False};p['decision_gate']='Per-case AA versus AB with all rows and CFS counters. Short gain requires separation; long must be reported even if no gain. Fixed cap2/3 chosen before measurement, no future-arrival oracle. Never update overall serving baseline.';(R/'specs/L012-protocol.json').open('x').write(json.dumps(p,indent=2)+'\n')
s=(R/'scripts/bench_tokenizer_image_v2.py').read_text();old="assert protocol['single_factor']=={'A':{'max_batch_size':1},'B':{'max_batch_size':32}}";new="assert protocol['single_factor']=={'A':{'max_batch_size':32},'B':{'max_batch_size':'predeclared_case_cap'}};assert protocol['candidate_caps']=={'tokenizer-cpu-c2':2,'tokenizer-cpu-c3':3}";assert s.count(old)==1;s=s.replace(old,new)
old="[('A0',1),('A1',1),('B',32)]";assert s.count(old)==1;s=s.replace(old,"[('A0',32),('A1',32),('B',protocol['candidate_caps'][args.case_key])]");old="'max_batch_size':1 if label.startswith('A') else 32";assert s.count(old)==1;s=s.replace(old,"'max_batch_size':actors[label].max_batch_size");s=s.replace('Per-case existing max_batch_size1/32 contrast only','Per-case existing max_batch_size32 versus predeclared cap2/3 contrast only');ast.parse(s);(R/'scripts/bench_tokenizer_cap_image.py').open('x').write(s)
s=(R/'scripts/materialize_tokenizer_benchmark_v2.py').read_text().replace('L011','L012').replace('l011','l012').replace('L012-protocol-v2.json','L012-protocol.json').replace('bench_tokenizer_image_v2.py','bench_tokenizer_cap_image.py');ast.parse(s);(R/'scripts/materialize_tokenizer_cap_benchmark.py').open('x').write(s)
print(json.dumps({'protocol':hashlib.sha256((R/'specs/L012-protocol.json').read_bytes()).hexdigest(),'probe':hashlib.sha256((R/'scripts/bench_tokenizer_cap_image.py').read_bytes()).hexdigest()}))
